app_css:
.tool-app-leadfile{font-family:inherit;max-width:960px;margin:0 auto;padding:8px 4px 32px;color:#111827}
.tool-app-leadfile .lf-tabs{display:flex;gap:8px;margin-bottom:18px;border-bottom:2px solid #e5e7eb;padding-bottom:0}
.tool-app-leadfile .lf-tab{background:none;border:none;border-bottom:3px solid transparent;padding:10px 14px;font-size:15px;font-weight:600;color:#6b7280;cursor:pointer}
.tool-app-leadfile .lf-tab.active{color:#1E40A8;border-bottom-color:#1E40A8}
.tool-app-leadfile .lf-pane{margin-bottom:24px}
.tool-app-leadfile .lf-row{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-bottom:14px;flex-wrap:wrap}
.tool-app-leadfile .lf-headline h3{margin:0 0 4px;font-size:20px}
.tool-app-leadfile .lf-headline p{margin:0;color:#6b7280;font-size:14px}
.tool-app-leadfile .lf-card{background:#f9fafb;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:16px}
.tool-app-leadfile .lf-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-bottom:14px}
.tool-app-leadfile .lf-grid label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:600;color:#374151}
.tool-app-leadfile .lf-grid input,.tool-app-leadfile .lf-grid select{padding:9px 11px;border:1px solid #d1d5db;border-radius:8px;font-size:14px;font-weight:400}
.tool-app-leadfile .lf-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
.tool-app-leadfile .lf-btn{background:#1E40A8;color:#fff;border:none;border-radius:8px;padding:10px 18px;font-size:14px;font-weight:600;cursor:pointer}
.tool-app-leadfile .lf-btn:hover{background:#1e3a8a}
.tool-app-leadfile .lf-btn-ghost{background:#fff;color:#1E40A8;border:1px solid #bfdbfe}
.tool-app-leadfile .lf-btn-ghost:hover{background:#eff6ff}
.tool-app-leadfile .lf-filelabel{cursor:pointer;display:inline-block}
.tool-app-leadfile .lf-job{border:1px solid #e5e7eb;border-radius:12px;padding:16px 18px;margin-bottom:12px;background:#fff}
.tool-app-leadfile .lf-job-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.tool-app-leadfile .lf-job-top b{font-size:16px}
.tool-app-leadfile .lf-meta{color:#6b7280;font-size:13px;margin-top:4px}
.tool-app-leadfile .lf-bar{height:8px;background:#e5e7eb;border-radius:99px;margin-top:10px;overflow:hidden}
.tool-app-leadfile .lf-bar i{display:block;height:100%;background:#1E40A8;border-radius:99px}
.tool-app-leadfile .lf-status{display:inline-block;padding:4px 12px;border-radius:99px;font-size:12px;font-weight:700;margin-left:8px}
.tool-app-leadfile .lf-done{background:#dcfce7;color:#166534}
.tool-app-leadfile .lf-progress{background:#fef3c7;color:#92400e}
.tool-app-leadfile .lf-todo{background:#f3f4f6;color:#6b7280}
.tool-app-leadfile .lf-joba{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap}
.tool-app-leadfile .lf-link{background:none;border:none;color:#1E40A8;font-size:13px;font-weight:600;cursor:pointer;padding:4px 2px}
.tool-app-leadfile .lf-link.danger{color:#dc2626}
.tool-app-leadfile .lf-check{display:flex;gap:12px;align-items:flex-start;padding:12px 0;border-bottom:1px solid #f3f4f6}
.tool-app-leadfile .lf-check:last-child{border-bottom:none}
.tool-app-leadfile .lf-check input[type=checkbox]{width:20px;height:20px;margin-top:2px;accent-color:#1E40A8;flex-shrink:0}
.tool-app-leadfile .lf-check b{display:block;font-size:14px}
.tool-app-leadfile .lf-check small{display:block;color:#6b7280;font-size:12.5px;margin-top:2px}
.tool-app-leadfile .lf-sub{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:8px}
.tool-app-leadfile .lf-sub input,.tool-app-leadfile .lf-sub select{padding:7px 9px;border:1px solid #d1d5db;border-radius:7px;font-size:13px;width:100%;box-sizing:border-box}
.tool-app-leadfile .lf-cert{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid #e5e7eb;border-radius:12px;padding:14px 18px;margin-bottom:10px;background:#fff;flex-wrap:wrap}
.tool-app-leadfile .lf-cert b{font-size:15px}
.tool-app-leadfile .lf-cert small{color:#6b7280;display:block;font-size:12.5px;margin-top:2px}
.tool-app-leadfile .lf-days{font-size:13px;font-weight:700;padding:6px 12px;border-radius:99px;white-space:nowrap}
.tool-app-leadfile .lf-ok{background:#dcfce7;color:#166534}
.tool-app-leadfile .lf-warn{background:#fef3c7;color:#92400e}
.tool-app-leadfile .lf-bad{background:#fee2e2;color:#991b1b}
.tool-app-leadfile .lf-hint{color:#6b7280;font-size:13px;margin-top:12px}
.tool-app-leadfile .lf-empty{color:#6b7280;background:#f9fafb;border:1px dashed #d1d5db;border-radius:12px;padding:28px;text-align:center;font-size:14px}
.tool-app-leadfile .lf-print{display:none}
@media print{
  .tool-app-leadfile .lf-no-print{display:none!important}
  .tool-app-leadfile .lf-print{display:block}
  .tool-app-leadfile .lf-print h2{margin:0 0 4px}
  .tool-app-leadfile .lf-print table{width:100%;border-collapse:collapse;margin-top:12px}
  .tool-app-leadfile .lf-print th,.tool-app-leadfile .lf-print td{border:1px solid #999;padding:8px;text-align:left;font-size:13px}
  .tool-app-leadfile .lf-print .lf-sig{margin-top:40px;display:flex;gap:40px}
  .tool-app-leadfile .lf-print .lf-sig div{flex:1;border-top:1px solid #333;padding-top:6px;font-size:12px;color:#555}
}

app_js:
(function(){
'use strict';
function gid(id){return document.getElementById(id);}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function uid(){return 'x'+Date.now().toString(36)+Math.floor(Math.random()*1e6).toString(36);}
var LS='leadfile.v1';
function load(){try{var d=JSON.parse(localStorage.getItem(LS));if(d&&d.jobs&&d.certs)return d;}catch(e){}return {jobs:[],certs:[]};}
function save(){try{localStorage.setItem(LS,JSON.stringify(state));}catch(e){}}
var state=load();
var openJob=null;

var CHECKS=[
 {k:'pamphlet',t:'Renovate Right pamphlet delivered',d:'Give the EPA Renovate Right pamphlet to the occupant before work starts. Record the date and how it was delivered.',f:['pdate','pmethod']},
 {k:'test',t:'Lead test result recorded',d:'Test the surfaces you will disturb with an EPA-recognized kit, or formally assume lead paint. Record the kit and result.',f:['tkid','tresult']},
 {k:'renovator',t:'Certified renovator assigned',d:'A certified renovator must be assigned to the job and present for setup, cleaning, and verification.',f:['rname']},
 {k:'training',t:'Crew lead-safe training documented',d:'All workers on the job are trained in lead-safe work practices and you have the training records on file.',f:[]},
 {k:'cleaning',t:'Cleaning verification completed',d:'After the job, perform cleaning verification (wet-cloth compare) and record the date and pass/fail.',f:['cdate','cresult']},
 {k:'records',t:'Record package archived',d:'Keep this job\u2019s full record package for at least 3 years from the job\u2019s completion.',f:[]}
];

function daysLeft(iso){var t=new Date(iso+'T23:59:59');var n=new Date();var ms=t-n;return Math.ceil(ms/86400000);}
function fmtDate(iso){if(!iso)return '';var p=iso.split('-');return p.length===3?(p[1]+'/'+p[2]+'/'+p[0]):iso;}
function jobPct(j){var n=0;CHECKS.forEach(function(c){if(j.check[c.k])n++;});return Math.round(n/CHECKS.length*100);}
function pathLabel(p){return {'tested-lead':'Tested - lead found','tested-none':'Tested - no lead','assumed':'Assumed lead paint','exempt':'Exempt'}[p]||p;}

function switchTab(which){['jobs','certs','data'].forEach(function(t){gid('lf-tab-'+t).classList.toggle('active',t===which);gid('lf-pane-'+t).hidden=t!==which;});if(which!=='jobs'){openJob=null;renderDetail();}if(which==='data'){renderCounts();}}

function renderJobs(){
 var box=gid('lf-jobs');
 if(!state.jobs.length){box.innerHTML='<div class="lf-empty">No jobs yet. Add your first job to start building its EPA record package.</div>';return;}
 var html=state.jobs.slice().reverse().map(function(j){
  var pct=jobPct(j);
  var cls=pct===100?'lf-done':(pct>0?'lf-progress':'lf-todo');
  var lbl=pct===100?'Complete':(pct>0?pct+'%':'Not started');
  var bits=[fmtDate(j.start)||'no date', pathLabel(j.path)];
  if(j.year)bits.push('built '+esc(j.year));
  return '<div class="lf-job"><div class="lf-job-top"><div><b>'+esc(j.addr)+'</b><span class="lf-status '+cls+'">'+lbl+'</span><div class="lf-meta">'+bits.join(' &middot; ')+'</div></div>'+
   '<div class="lf-joba"><button class="lf-link" data-open="'+j.id+'" type="button">Open record</button>'+
   '<button class="lf-link" data-print="'+j.id+'" type="button">Print package</button>'+
   '<button class="lf-link danger" data-del="'+j.id+'" type="button">Delete</button></div></div>'+
   '<div class="lf-bar"><i style="width:'+pct+'%"></i></div></div>';
 }).join('');
 box.innerHTML=html;
 box.querySelectorAll('[data-open]').forEach(function(b){b.onclick=function(){openJob=b.getAttribute('data-open');renderDetail();};});
 box.querySelectorAll('[data-del]').forEach(function(b){b.onclick=function(){if(confirm('Delete this job record?')){state.jobs=state.jobs.filter(function(x){return x.id!==b.getAttribute('data-del');});if(openJob===b.getAttribute('data-del'))openJob=null;save();renderJobs();renderDetail();}};});
 box.querySelectorAll('[data-print]').forEach(function(b){b.onclick=function(){printPackage(b.getAttribute('data-print'));};});
}

function renderDetail(){
 var box=gid('lf-detail');
 if(!openJob){box.innerHTML='';return;}
 var j=state.jobs.filter(function(x){return x.id===openJob;})[0];
 if(!j){openJob=null;box.innerHTML='';return;}
 var pct=jobPct(j);
 var html='<div class="lf-card"><div class="lf-job-top"><div><b>'+esc(j.addr)+'</b><div class="lf-meta">'+(fmtDate(j.start)||'no date')+' &middot; '+pathLabel(j.path)+(j.year?' &middot; built '+esc(j.year):'')+' &middot; '+pct+'% of record package</div></div>'+
  '<button class="lf-btn lf-btn-ghost lf-no-print" id="lf-close" type="button">Close</button></div>';
 html+=CHECKS.map(function(c){
  var on=!!j.check[c.k];var f=j.fields||{};
  var sub='';
  if(c.k==='pamphlet')sub='<input data-f="pdate" type="date" value="'+esc(f.pdate||'')+'" placeholder="Date delivered"><select data-f="pmethod"><option value="">Delivery method</option>'+['Hand-delivered','Email','Text / photo proof','Posted on door'].map(function(m){return '<option'+(f.pmethod===m?' selected':'')+'>'+m+'</option>';}).join('')+'</select>';
  if(c.k==='test')sub='<input data-f="tkid" type="text" value="'+esc(f.tkid||'')+'" placeholder="Test kit (e.g. 3M LeadCheck)"><select data-f="tresult"><option value="">Result</option>'+['Lead found','No lead found','Assumed lead'].map(function(m){return '<option'+(f.tresult===m?' selected':'')+'>'+m+'</option>';}).join('')+'</select>';
  if(c.k==='renovator')sub='<input data-f="rname" type="text" value="'+esc(f.rname||'')+'" placeholder="Renovator name">';
  if(c.k==='cleaning')sub='<input data-f="cdate" type="date" value="'+esc(f.cdate||'')+'" placeholder="Verification date"><select data-f="cresult"><option value="">Outcome</option>'+['Passed','Failed - recleaned','Failed'].map(function(m){return '<option'+(f.cresult===m?' selected':'')+'>'+m+'</option>';}).join('')+'</select>';
  if(sub)sub='<div class="lf-sub">'+sub+'</div>';
  return '<div class="lf-check lf-no-print"><input type="checkbox" data-c="'+c.k+'"'+(on?' checked':'')+'><div><b>'+c.t+'</b><small>'+c.d+'</small>'+sub+'</div></div>';
 }).join('');
 html+='<div class="lf-actions lf-no-print"><button class="lf-btn" id="lf-print2" type="button">Print compliance package</button></div></div>';
 box.innerHTML=html;
 gid('lf-close').onclick=function(){openJob=null;renderDetail();};
 gid('lf-print2').onclick=function(){printPackage(openJob);};
 box.querySelectorAll('[data-c]').forEach(function(cb){cb.onchange=function(){j.check[cb.getAttribute('data-c')]=cb.checked;save();renderJobs();renderDetail();};});
 box.querySelectorAll('[data-f]').forEach(function(inp){inp.onchange=function(){j.fields[inp.getAttribute('data-f')]=inp.value;save();};});
}

function printPackage(id){
 var j=state.jobs.filter(function(x){return x.id===id;})[0];
 if(!j)return;
 var rows=CHECKS.map(function(c){
  var f=j.fields||{};var det='';
  if(c.k==='pamphlet')det=(f.pdate?fmtDate(f.pdate):'')+(f.pmethod?' - '+f.pmethod:'');
  if(c.k==='test')det=(f.tkid||'')+(f.tresult?' - '+f.tresult:'');
  if(c.k==='renovator')det=f.rname||'';
  if(c.k==='cleaning')det=(f.cdate?fmtDate(f.cdate):'')+(f.cresult?' - '+f.cresult:'');
  return '<tr><td>'+(j.check[c.k]?'&#10003;':'&square;')+'</td><td>'+c.t+'</td><td>'+esc(det)+'</td></tr>';
 }).join('');
 gid('lf-print').innerHTML='<h2>EPA RRP Record Package</h2><p><b>'+esc(j.addr)+'</b><br>Start: '+(fmtDate(j.start)||'n/a')+' &middot; Lead path: '+esc(pathLabel(j.path))+(j.year?' &middot; Built: '+esc(j.year):'')+'<br>Package completed: '+jobPct(j)+'%</p>'+
  '<table><tr><th style="width:40px">Done</th><th>Required record</th><th>Detail</th></tr>'+rows+'</table>'+
  '<p style="font-size:12px;color:#555">Retain this package for at least 3 years from the job\u2019s completion date per 40 CFR 745.86.</p>'+
  '<div class="lf-sig"><div>Certified renovator signature / date</div><div>Firm representative signature / date</div></div>';
 window.print();
}

function renderCerts(){
 var box=gid('lf-certs');
 if(!state.certs.length){box.innerHTML='<div class="lf-empty">No certifications on file. Add your firm certification and each certified renovator.</div>';return;}
 var rows=state.certs.map(function(c){
  var d=daysLeft(c.exp);
  var cls=d<0?'lf-bad':(d<=90?'lf-bad':(d<=180?'lf-warn':'lf-ok'));
  var lbl=d<0?'EXPIRED '+Math.abs(d)+'d ago':(d+' days left');
  return '<div class="lf-cert"><div><b>'+esc(c.name)+'</b><small>'+(c.kind==='firm'?'Firm certification':'Certified renovator')+(c.num?' &middot; '+esc(c.num):'')+' &middot; expires '+fmtDate(c.exp)+'</small></div>'+
   '<div class="lf-joba"><span class="lf-days '+cls+'">'+lbl+'</span><button class="lf-link danger" data-cdel="'+c.id+'" type="button">Remove</button></div></div>';
 }).join('');
 var sorted=state.certs.slice().sort(function(a,b){return a.exp<b.exp?-1:1;});
 box.innerHTML=sorted.map(function(c){
  var d=daysLeft(c.exp);
  var cls=d<0?'lf-bad':(d<=90?'lf-bad':(d<=180?'lf-warn':'lf-ok'));
  var lbl=d<0?'EXPIRED '+Math.abs(d)+'d ago':(d+' days left');
  return '<div class="lf-cert"><div><b>'+esc(c.name)+'</b><small>'+(c.kind==='firm'?'Firm certification':'Certified renovator')+(c.num?' &middot; '+esc(c.num):'')+' &middot; expires '+fmtDate(c.exp)+'</small></div>'+
   '<div class="lf-joba"><span class="lf-days '+cls+'">'+lbl+'</span><button class="lf-link danger" data-cdel="'+c.id+'" type="button">Remove</button></div></div>';
 }).join('');
 box.querySelectorAll('[data-cdel]').forEach(function(b){b.onclick=function(){if(confirm('Remove this certification?')){state.certs=state.certs.filter(function(x){return x.id!==b.getAttribute('data-cdel');});save();renderCerts();}};});
}

function renderCounts(){
 var n=state.jobs.filter(function(j){return jobPct(j)===100;}).length;
 gid('lf-counts').textContent=state.jobs.length+' jobs ('+n+' with complete packages) and '+state.certs.length+' certifications stored in this browser.';
}

function bind(){
 ['jobs','certs','data'].forEach(function(t){gid('lf-tab-'+t).onclick=function(){switchTab(t);};});
 var jf=gid('lf-jobform');
 gid('lf-newjob').onclick=function(){jf.hidden=false;gid('lf-addr').focus();};
 gid('lf-canceljob').onclick=function(){jf.hidden=true;jf.reset();};
 jf.onsubmit=function(e){e.preventDefault();
  var yr=gid('lf-year').value;
  var path=gid('lf-path').value;
  if(yr&&parseInt(yr,10)<1978&&path==='exempt'){if(!confirm('Year built is before 1978 - are you sure this job is exempt?'))return;}
  state.jobs.push({id:uid(),addr:gid('lf-addr').value.trim()||'Untitled job',year:yr,start:gid('lf-start').value,path:path,check:{},fields:{}});
  save();jf.hidden=true;jf.reset();renderJobs();};
 var cf=gid('lf-certform');
 gid('lf-newcert').onclick=function(){cf.hidden=false;gid('lf-cname').focus();};
 gid('lf-cancelcert').onclick=function(){cf.hidden=true;cf.reset();};
 cf.onsubmit=function(e){e.preventDefault();
  state.certs.push({id:uid(),kind:gid('lf-ckind').value,name:gid('lf-cname').value.trim()||'Unnamed',exp:gid('lf-cexp').value,num:gid('lf-cnum').value.trim()});
  save();cf.hidden=true;cf.reset();renderCerts();};
 gid('lf-export').onclick=function(){
  var blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='leadfile-backup.json';a.click();
  setTimeout(function(){URL.revokeObjectURL(a.href);},2000);};
 gid('lf-import').onchange=function(e){
  var f=e.target.files[0];if(!f)return;
  var r=new FileReader();
  r.onload=function(){try{var d=JSON.parse(r.result);if(d&&d.jobs&&d.certs){state=d;save();renderJobs();renderCerts();renderDetail();renderCounts();}else{alert('That file does not look like a LeadFile backup.');}}catch(err){alert('Could not read that backup file.');}};
  r.readAsText(f);e.target.value='';};
}

renderJobs();renderCerts();bind();
})();
